theme-color: #000; --swiper-navigation-size: 44px; --swiper-pagination-bullet-size: 6px; --swiper-pagination-bullet-horizontal-gap: 6px; --widgets-spacing: 20px 20px; --widgets-spacing-row: 20px; --widgets-spacing-column: 20px; margin-bottom: 20px; min-width: 0px; margin-block-end: 0px; text-align: center; max-width: 100%;\"><div class=\"elementor-widget-container\" style=\"transition: background 0.3s, border 0.3s, border-radius 0.3s, box-shadow 0.3s, transform 0.4s; height: 30.3854px;\"><span id=\"elementor-toc__heading-anchor-4\" class=\"elementor-menu-anchor \"></span><span id=\"elementor-toc__heading-anchor-4\" class=\"elementor-menu-anchor \"></span><h2 class=\"elementor-heading-title elementor-size-default\" style=\"color: rgb(0, 0, 0); font-family: Karla, sans-serif; font-weight: 600; line-height: 30.39px; margin-block: 0.5rem 1rem; font-size: 20px; margin: 0px; padding: 0px; letter-spacing: -0.5px;\">Start your assessment</h2></div></div><div class=\"elementor-element elementor-element-8802124 elementor-view-default elementor-widget elementor-widget-icon\" data-id=\"8802124\" data-element_type=\"widget\" data-widget_type=\"icon.default\" style=\"--flex-direction: initial; --flex-wrap: initial; --justify-content: initial; --align-items: initial; --align-content: initial; --gap: initial; --flex-basis: initial; --flex-grow: initial; --flex-shrink: initial; --order: initial; --align-self: initial; flex: 0 1 auto; order: 0; align-self: auto; flex-flow: row; place-content: normal; align-items: normal; gap: normal; position: relative; --swiper-theme-color: #000; --swiper-navigation-size: 44px; --swiper-pagination-bullet-size: 6px; --swiper-pagination-bullet-horizontal-gap: 6px; --widgets-spacing: 20px 20px; --widgets-spacing-row: 20px; --widgets-spacing-column: 20px; min-width: 0px; margin-block-end: 0px; max-width: 100%;\"><div class=\"elementor-widget-container\" style=\"transition: background 0.3s, border 0.3s, border-radius 0.3s, box-shadow 0.3s, transform 0.4s; height: 30.6667px; padding: 6px 0px 0px;\"><div class=\"elementor-icon-wrapper\" style=\"text-align: center;\"><div class=\"elementor-icon\" style=\"display: inline-block; line-height: 1; transition: 0.3s; color: rgb(0, 0, 0); font-size: 20px; border-color: rgb(0, 0, 0);\"><span aria-hidden=\"true\" class=\"fas fa-arrow-right\" style=\"display: block; font-family: &quot;Font Awesome 5 Free&quot;; width: 1em; height: 1em; position: relative;\"></span></div></div></div></div></a></div><div class=\"elementor-element elementor-element-3c4cd18 e-flex e-con-boxed e-con e-parent e-lazyloaded\" data-id=\"3c4cd18\" data-element_type=\"container\" style=\"--flex-direction: column; --flex-wrap: initial; --justify-content: initial; --align-items: initial; --align-content: initial; --gap: 20px 20px; --flex-basis: auto; --flex-grow: 0; --flex-shrink: 1; --order: initial; --align-self: initial; flex: 0 1 auto; order: 0; align-self: auto; --border-radius: 0; --border-top-width: 0px; --border-right-width: 0px; --border-bottom-width: 0px; --border-left-width: 0px; --border-style: initial; --border-color: initial; --container-widget-width: 100%; --container-widget-height: initial; --container-widget-flex-grow: 0; --container-widget-align-self: initial; --content-width: min(100%,1200px); --width: 100%; --min-height: initial; --height: auto; --text-align: initial; --margin-top: 0px; --margin-right: auto; --margin-bottom: 0px; --margin-left: auto; --padding-top: 0px; --padding-right: 0px; --padding-bottom: 0px; --padding-left: 0px; --position: relative; --z-index: revert; --overflow: visible; --overlay-mix-blend-mode: initial; --overlay-opacity: 1; --overlay-transition: 0.3s; --e-con-grid-template-columns: repeat(3,1fr); --e-con-grid-template-rows: repeat(2,1fr); position: relative; width: 100%; min-width: 0px; min-height: auto; height: auto; border-radius: 0px; z-index: auto; overflow: visible; transition: 0.5s ease-in-out; --flex-wrap-mobile: wrap; margin-block: 0px; margin-inline: auto; padding-inline: 0px; --margin-block-start: 0px; --margin-block-end: 0px; --margin-inline-start: auto; --margin-inline-end: auto; --padding-inline-start: 0px; --padding-inline-end: 0px; --padding-block-start: 0px; --padding-block-end: 0px; --border-block-start-width: 0px; --border-block-end-width: 0px; --border-inline-start-width: 0px; --border-inline-end-width: 0px; display: flex; text-align: initial; gap: initial; --swiper-theme-color: #000; --swiper-navigation-size: 44px; --swiper-pagination-bullet-size: 6px; --swiper-pagination-bullet-horizontal-gap: 6px; --container-max-width: 1200px; --container-default-padding-top: 0px; --container-default-padding-right: 0px; --container-default-padding-bottom: 0px; --container-default-padding-left: 0px; --widgets-spacing: 20px 20px; --widgets-spacing-row: 20px; --widgets-spacing-column: 20px; flex-flow: column; place-content: normal; align-items: normal; max-width: 100%; padding: 0px 5vw; --display: flex; --background-transition: 0.3s; box-shadow: rgba(0, 0, 0, 0.5) 0px 0px 0px 0px;\"><div class=\"e-con-inner\" style=\"padding-block: 0px; display: flex; gap: 20px; width: 700.5px; max-width: min(100%, 1200px); margin: 0px auto; padding-inline: 0px; height: 0px; flex-flow: column; place-content: normal; align-items: normal; flex: 1 1 auto; align-self: auto;\"></div></div></div><h2 id=\"h-what-dose-do-i-start-the-wegovy-pill-at-after-mounjaro-nbsp\" class=\"wp-block-heading\" style=\"color: rgb(0, 18, 63); font-family: Karla, sans-serif; font-weight: 700; line-height: 30.39px; margin-block: 0.5rem 1rem; font-size: 26px; margin-top: 20px; background-color: rgb(249, 250, 251);\">What dose do I start the Wegovy pill at after Mounjaro?&nbsp;</h2><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\"><span style=\"font-weight: bolder;\">Your Wegovy pill starting dose will depend on your current Mounjaro dose. </span>While Wegovy and Mounjaro operate differently, you can swap between them. Mounjaro acts on two appetite hormones (GLP-1 and GIT). Semaglutide, the active ingredient in Wegovy, acts on one. This means the doses are not directly equivalent, but the table below gives a starting point. Our clinical team will review your medical history and confirm the right dose schedule for you.</p><figure class=\"wp-block-table\" style=\"margin: 0px 0px 1em; overflow-x: auto; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\"><table class=\"has-fixed-layout\" style=\"background-color: transparent; border-spacing: 0px; font-size: 0.9em; margin-block-end: 15px; width: 828.5px; table-layout: fixed;\"><tbody><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\"><span style=\"font-weight: bolder;\">Mounjaro Injection Dose</span></td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\"><span style=\"font-weight: bolder;\">Wegovy Pill Dose</span></td></tr><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\">15mg, 12.5mg, 10mg or 7.5mg</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\">25mg</td></tr><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\">2.5mg or 5mg</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\">9mg</td></tr><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\">–</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\">4mg</td></tr><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\">–</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\">1.5mg</td></tr></tbody></table></figure><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\">For new patients, Wegovy pill dose escalation runs from 1.5 mg through 4 mg, 9 mg and a 25 mg maintenance dose. Everyone spends at least 30 days on their current dose before they can step up.</p><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\"><span style=\"font-size: 1rem;\">Wegovy tablets come with strict timing rules that will be new to anyone moving from weekly injections. You take the tablet first thing in the morning with a half glass of water (120 mL maximum). Then wait 30 minutes before eating, drinking, or taking other medication. Food reduces absorption significantly, and most patients find this harder to stick to than a weekly injection.</span></p><h3 id=\"h-will-i-gain-weight-during-the-transition\" class=\"wp-block-heading\" style=\"color: rgb(0, 18, 63); font-family: Karla, sans-serif; font-weight: 700; line-height: 28.06px; margin-block: 0.5rem 1rem; font-size: 24px; margin-top: 20px; background-color: rgb(249, 250, 251);\">Will I gain weight during the transition?</h3><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\"><span style=\"font-weight: bolder;\">Some patients may find Wegovy pills less effective than Mounjaro, and weight loss progress may stall temporarily. </span>This usually stabilises within a couple of months of reaching the 25 mg maintenance dose.<span style=\"font-weight: bolder;\">&nbsp;</span></p><h2 id=\"h-what-side-effects-should-i-expect-when-switching\" class=\"wp-block-heading\" style=\"color: rgb(0, 18, 63); font-family: Karla, sans-serif; font-weight: 700; line-height: 30.39px; margin-block: 0.5rem 1rem; font-size: 26px; margin-top: 20px; background-color: rgb(249, 250, 251);\">What side effects should I expect when switching?</h2><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\"><span style=\"font-weight: bolder;\">Nausea, constipation, and diarrhoea are most common during dose escalation. </span>Around three in four people in the OASIS 4 trial reported gut symptoms at some point, though most settled with time. The side effects of switching from Mounjaro to Wegovy are not always predictable. Tolerating one drug well does not guarantee tolerating the other.</p><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\">Two safety updates are worth knowing about. In January 2026, the MHRA strengthened its <a href=\"https://www.gov.uk/drug-safety-update/glp-1-receptor-agonists-and-dual-glp-1-slash-gip-receptor-agonists-strengthened-warnings-on-acute-pancreatitis-including-necrotising-and-fatal-cases\" target=\"_blank\" rel=\"noreferrer noopener nofollow\" style=\"color: rgb(29, 92, 255); text-decoration: none; box-shadow: none; line-height: 20px;\">pancreatitis warning</a> for all GLP-1 medications, including Mounjaro and Wegovy. Any new severe stomach pain during a switch needs urgent attention. The MHRA also flagged NAION in February 2026, a rare eye condition linked to semaglutide that can cause sudden vision loss in one eye.</p><h2 id=\"h-when-should-i-see-a-doctor\" class=\"wp-block-heading\" style=\"color: rgb(0, 18, 63); font-family: Karla, sans-serif; font-weight: 700; line-height: 30.39px; margin-block: 0.5rem 1rem; font-size: 26px; margin-top: 20px; background-color: rgb(249, 250, 251);\">When should I see a doctor?</h2><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\"><span style=\"font-weight: bolder;\">Not every symptom needs the same response.</span> If your side effects are mild or you have questions about your starting dose, talk to our clinical team. We can adjust timing, slow the dose ladder, or suggest small changes that usually settle the gut symptoms within a week or two.</p><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\">For more serious symptoms, <span style=\"font-weight: bolder;\">stop your medication</span> and seek the appropriate medical attention:</p><figure class=\"wp-block-table\" style=\"margin: 0px 0px 1em; overflow-x: auto; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\"><table class=\"has-fixed-layout\" style=\"background-color: transparent; border-spacing: 0px; font-size: 0.9em; margin-block-end: 15px; width: 828.5px; table-layout: fixed;\"><tbody><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\"><span style=\"font-weight: bolder;\">Symptom</span></td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\"><span style=\"font-weight: bolder;\">What it may indicate</span></td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\"><span style=\"font-weight: bolder;\">Who to contact</span></td></tr><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\">Sustained vomiting (unable to keep fluids down for 24+ hours)</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\">Dehydration risk; may need IV fluids or dose adjustment</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\"><span style=\"font-weight: bolder;\">GP or <a href=\"tel:111\" target=\"_blank\" rel=\"noreferrer noopener nofollow\" style=\"color: rgb(29, 92, 255); text-decoration: none; box-shadow: none; font-size: 16px; font-weight: 400; line-height: 20px;\">NHS 111</a></span> Same day</td></tr><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\">Yellowing of skin or whites of eyes, pale stools, or dark urine</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\">Possible liver or gallbladder problem</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\"><span style=\"font-weight: bolder;\">GP or <a href=\"tel:111\" type=\"tel\" id=\"tel:111\" target=\"_blank\" rel=\"noreferrer noopener nofollow\" style=\"color: rgb(29, 92, 255); text-decoration: none; box-shadow: none; font-size: 16px; font-weight: 400; line-height: 20px;\">NHS 111</a></span> Same day</td></tr><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\">Pain in the upper-right abdomen</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\">Possible gallbladder inflammation</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\"><span style=\"font-weight: bolder;\">GP or <a href=\"tel:111\" type=\"tel\" id=\"tel:111\" target=\"_blank\" rel=\"noreferrer noopener nofollow\" style=\"color: rgb(29, 92, 255); text-decoration: none; box-shadow: none; font-size: 16px; font-weight: 400; line-height: 20px;\">NHS 111</a></span> Same day<br><span style=\"font-weight: bolder;\">A&amp;E if severe</span></td></tr><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\">Lump in neck, persistent hoarseness, or difficulty swallowing</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\">Thyroid changes; needs investigation</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\"><span style=\"font-weight: bolder;\">GP or <a href=\"tel:111\" type=\"tel\" id=\"tel:111\" target=\"_blank\" rel=\"noreferrer noopener nofollow\" style=\"color: rgb(29, 92, 255); text-decoration: none; box-shadow: none; font-size: 16px; font-weight: 400; line-height: 20px;\">NHS 111</a></span> Same day</td></tr><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\">Sudden blurring or loss of vision in one eye</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\">Possible NAION (rare eye condition linked to semaglutide)</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\"><span style=\"font-weight: bolder;\"><a href=\"tel:111\" type=\"tel\" id=\"tel:111\" target=\"_blank\" rel=\"noreferrer noopener nofollow\" style=\"color: rgb(29, 92, 255); text-decoration: none; box-shadow: none; font-size: 16px; font-weight: 400; line-height: 20px;\">NHS 111</a> or eye casualty</span> Same day</td></tr><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\">Swelling of lips, face, or throat; sudden difficulty breathing</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\">Severe allergic reaction</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\"><span style=\"font-weight: bolder;\"><font color=\"#1d5cff\"><span style=\"text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; font-size: 16px; font-weight: 400; line-height: 20px;\">Dial 999</span></font> </span>Immediately</td></tr><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\">Severe, persistent stomach pain spreading to the back, with or without vomiting</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\">Possible acute pancreatitis</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\"><span style=\"font-weight: bolder;\">A&amp;E</span> Immediately</td></tr><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\">Confusion, unusually dark urine, or not passing urine for many hours</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\">Severe dehydration</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\"><span style=\"font-weight: bolder;\">A&amp;E </span>Immediately</td></tr></tbody></table></figure><h2 id=\"h-frequently-asked-questions\" class=\"wp-block-heading\" style=\"color: rgb(0, 18, 63); font-family: Karla, sans-serif; font-weight: 700; line-height: 30.39px; margin-block: 0.5rem 1rem; font-size: 26px; margin-top: 20px; background-color: rgb(249, 250, 251);\">Frequently asked questions</h2><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\"><span style=\"font-weight: bolder;\">Can you switch from Wegovy injection to the Wegovy pill?</span></p><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\">Yes. The MHRA confirmed that patients on 2.4 mg Wegovy injections can switch directly to the 25 mg Wegovy tablet without a washout. Both formulations contain semaglutide, so your body is already adjusted to the active ingredient. Lower doses can switch to an approximately equivalent dose. Our clinical team can arrange this for you.</p><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\"><span style=\"font-weight: bolder;\">Can I switch back to Mounjaro from the Wegovy pill?</span></p><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\">Yes, but the switch back is more cautious. Mounjaro works on two appetite hormones (GIP and GLP-1), and your body will not have been exposed to the GIP pathway while on the Wegovy pill. Because of this, our clinical team will restart you at a lower Mounjaro dose to reduce the risk of side effects.&nbsp;</p><figure class=\"wp-block-table\" style=\"margin: 0px 0px 1em; overflow-x: auto; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\"><table class=\"has-fixed-layout\" style=\"background-color: transparent; border-spacing: 0px; font-size: 0.9em; margin-block-end: 15px; width: 828.5px; table-layout: fixed;\"><tbody><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\"><span style=\"font-weight: bolder;\">Wegovy pill dose</span></td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\"><span style=\"font-weight: bolder;\">Mounjaro restart dose</span></td></tr><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\">25 mg</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\">5 mg</td></tr><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\">9 mg, 4 mg, 1.5 mg</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\">2.5 mg</td></tr></tbody></table></figure><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\">A washout period between stopping the Wegovy pill and starting Mounjaro will also apply. Our clinical team can talk you through this if you are not getting on with the tablet.</p><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\"><span style=\"font-weight: bolder;\">Can I take the Wegovy pill if I have type 2 diabetes?</span></p><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\">The Wegovy pill is licensed for adults with a BMI of 27 or above who have a weight-related health condition, which includes type 2 diabetes. The OASIS 4 trial tested the tablet in adults without diabetes, so the weight loss data comes from that population. A lower-dose version of oral semaglutide (Rybelsus) is already prescribed for blood sugar control.&nbsp;</p><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\">Make sure to let our clinical team know if you have type 2 diabetes and wish to start or switch a GLP-1 for weight loss, as your diabetes medications may need adjusting.</p><h2 id=\"h-key-takeaways\" class=\"wp-block-heading\" style=\"color: rgb(0, 18, 63); font-family: Karla, sans-serif; font-weight: 700; line-height: 30.39px; margin-block: 0.5rem 1rem; font-size: 26px; margin-top: 20px; background-color: rgb(249, 250, 251);\">Key takeaways</h2><ul class=\"wp-block-list\" style=\"background: rgb(249, 250, 251); border: 0px; margin-block: 0px; outline: 0px; vertical-align: baseline; padding: 0px; list-style-position: inside; color: rgb(29, 33, 36); font-family: Inter, sans-serif;\"><li style=\"background: transparent; border: 0px; margin-block: 0px; outline: 0px; vertical-align: baseline; padding: 0px; list-style-position: inside; margin-bottom: 12px;\">The Wegovy pill was approved in the UK on 11 June 2026 and is available through private prescribers. NHS access has not yet been confirmed.</li><li style=\"background: transparent; border: 0px; margin-block: 0px; outline: 0px; vertical-align: baseline; padding: 0px; list-style-position: inside; margin-bottom: 12px;\">We recommend a seven-day gap between your last Mounjaro injection and your first Wegovy pill.</li><li style=\"background: transparent; border: 0px; margin-block: 0px; outline: 0px; vertical-align: baseline; padding: 0px; list-style-position: inside; margin-bottom: 12px;\">Your Mounjaro dose maps to a Wegovy pill starting dose. Patients on 7.5 mg or above typically start at 25 mg.</li><li style=\"background: transparent; border: 0px; margin-block: 0px; outline: 0px; vertical-align: baseline; padding: 0px; list-style-position: inside; margin-bottom: 12px;\">Average weight loss is lower on the tablet than on Mounjaro: around 14% vs 20% for Mounjaro in trials.</li><li style=\"background: transparent; border: 0px; margin-block: 0px; outline: 0px; vertical-align: baseline; padding: 0px; list-style-position: inside; margin-bottom: 12px;\">Take the tablet on waking with a small sip of water. No food, drink, or other medicines for at least 30 minutes.</li></ul>', 'public/assets/uploads/feeb7e7857b9efaa7caaa44a16a66c88.webp', 'Yes — the Medicines and Healthcare Regulatory Agency (MHRA) approved the Wegovy pill on 11 June 2026, making it the first GLP-1 weight loss tablet licensed in the UK. It can be prescribed to adults wi', 'Yes — the Medicines and Healthcare Regulatory Agency (MHRA) approved the Wegovy pill on 11 June 2026, making it the first GLP-1 weight loss tablet licensed in the UK. It can be prescribed to adults with a BMI of 30 or above, or a BMI between 27 and 30 with at least one weight-related health conditio', 'Wegovy pill', 'can-i-switch-from-mounjaro-to-the-wegovy-pill', '2026-09-03 13:45:10', '2026-09-04 10:30:19');
INSERT INTO `blog` (`id`, `title`, `category_id`, `content`, `image`, `meta`, `short_desc`, `keyphrase`, `slug`, `created_at`, `updated_at`) VALUES
(2, 'Not Losing Weight on Foundayo: Why and What to Do', 1, '<h2 id=\"h-how-much-weight-can-i-lose-with-foundayo\" class=\"wp-block-heading\" style=\"color: rgb(0, 18, 63); font-family: Karla, sans-serif; font-weight: 700; line-height: 30.39px; margin-block: 0.5rem 1rem; font-size: 26px; margin-top: 20px; background-color: rgb(249, 250, 251);\">How much weight can I lose with Foundayo?</h2><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\"><span style=\"font-weight: bolder;\">In the ATTAIN-1 clinical trial, <a href=\"https://www.simpleonlinepharmacy.co.uk/online-doctor/weight-loss-pills/foundayo/\" data-type=\"link\" data-id=\"https://www.simpleonlinepharmacy.co.uk/online-doctor/weight-loss-pills/foundayo/\" style=\"color: rgb(29, 92, 255); text-decoration: none; box-shadow: none; font-weight: 400; line-height: 20px;\">the highest dose of Foundayo produced average weight loss of</a> 11.2% of body weight over 72 weeks.</span> For someone starting at 100kg, 11.2% works out at roughly 11kg. Adults in the placebo treatment group, given an inactive pill for comparison, 2.1% over the same 17 months. <a href=\"https://www.simpleonlinepharmacy.co.uk/health-advice/weight-loss/foundayo/foundayo-weight-loss-results/\" data-type=\"link\" data-id=\"https://www.simpleonlinepharmacy.co.uk/health-advice/weight-loss/foundayo/foundayo-weight-loss-results/\" style=\"color: rgb(29, 92, 255); text-decoration: none; box-shadow: none; line-height: 20px;\">Foundayo’s weight loss results</a> have been recorded in several clinical trails.</p><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\"><a href=\"https://www.nejm.org/doi/full/10.1056/NEJMoa2511774\" data-type=\"link\" data-id=\"https://www.nejm.org/doi/full/10.1056/NEJMoa2511774\" target=\"_blank\" rel=\"noreferrer noopener nofollow\" style=\"color: rgb(29, 92, 255); text-decoration: none; box-shadow: none; line-height: 20px;\">The ATTAIN-1 trial</a> enrolled 3,127 adults with obesity or overweight plus a weight-related condition. Just over half of the people on the top dose lost at least 10% of their starting weight. Around a third reached 15% or more, and close to one in five lost 20% or more.&nbsp;</p><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\">Everyone else lost under 10%, and a minority lost almost nothing at all. Two people can take the same daily pill, at the same dose, for the same length of time, and finish in completely different places.</p><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\">All four figures below come from ATTAIN-1, counting every participant whether or not they stayed on treatment.&nbsp;</p><figure class=\"wp-block-table\" style=\"margin: 0px 0px 1em; overflow-x: auto; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\"><table class=\"has-fixed-layout\" style=\"background-color: transparent; border-spacing: 0px; font-size: 0.9em; margin-block-end: 15px; width: 828.5px; table-layout: fixed;\"><tbody><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\"><span style=\"font-weight: bolder;\">Foundayo dose in ATTAIN-1</span></td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\"><span style=\"font-weight: bolder;\">Average weight change at 72 weeks</span></td></tr><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\">6mg</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\">7.5% loss</td></tr><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\">12mg</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\">8.4% loss</td></tr><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\">36mg</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; word-break: break-word;\">11.2% loss</td></tr><tr><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\">Placebo</td><td style=\"border-color: currentcolor; line-height: 1.5; padding: 0.5em; vertical-align: top; background-color: rgba(128, 128, 128, 0.07); word-break: break-word;\">2.1% loss</td></tr></tbody></table></figure><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\">The numbers on your Foundayo tablet box will not match the numbers in the headlines. ATTAIN-1 used capsules at 6mg, 12mg and 36mg. However, Foundayo is manufactured in tablet form. The lowest dose is 0.8mg, increasing to a maximum of 17.2mg. Foundayo tablets and capsules are not bioequivalent, meaning they don’t deliver the same amount of medicine into the body in the same way, so the available strengths differ between the two formulations.&nbsp;</p><p class=\"wp-block-paragraph\" style=\"margin-block: 0px 0.9rem; margin-bottom: 15px; color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\"><a href=\"https://www.medicines.org.uk/emc/product/102532/smpc\" data-type=\"link\" data-id=\"https://www.medicines.org.uk/emc/product/102532/smpc\" target=\"_blank\" rel=\"dofollow noreferrer noopener\" style=\"color: rgb(29, 92, 255); text-decoration: none; box-shadow: none; line-height: 20px;\">The UK Foundayo prescribing information</a> describes the <span style=\"font-weight: bolder;\">36mg orforglipron capsule as equal in effect to the 17.2mg tablet</span>. Foundayo weight loss results also build slowly, and the 11.2% trial figure reflects 17 months of consistent treatment.</p><div data-elementor-type=\"container\" data-elementor-id=\"19393\" class=\"elementor elementor-19393\" data-elementor-post-type=\"elementor_library\" style=\"color: rgb(29, 33, 36); font-family: Inter, sans-serif; background-color: rgb(249, 250, 251);\"><div class=\"elementor-element elementor-element-d726aa8 e-con-full e-flex e-con e-parent e-lazyloaded\" data-id=\"d726aa8\" data-element_type=\"container\" data-settings=\"{&quot;background_background&quot;:&quot;classic&quot;}\" style=\"--flex-direction: row; --flex-wrap: initial; --justify-content: center; --align-items: initial; --align-content: initial; --gap: 20px 20px; --flex-basis: auto; --flex-grow: 0; --flex-shrink: 1; --order: initial; --align-self: center; flex: 0 1 auto; order: 0; align-self: center; flex-flow: row; place-content: normal center; align-items: normal; gap: 20px; --border-radius: 20px 20px 20px 20px; --border-top-width: 0px; --border-right-width: 0px; --border-bottom-width: 0px; --border-left-width: 0px; --border-style: initial; --border-color: initial; --container-widget-width: initial; --container-widget-height: 100%; --container-widget-flex-grow: 1; --container-widget-align-self: stretch; --content-width: min(100%,1200px); --width: 100%; --min-height: 0px; --height: auto; --text-align: initial; --margin-top: 25px; --margin-right: 0px; --margin-bottom: 15px; --margin-left: 0px; --padding-top: 15px; --padding-right: 15px; --padding-bottom: 15px; --padding-left: 15px; --position: relative; --z-index: revert; --overflow: visible; --overlay-mix-blend-mode: initial; --overlay-opacity: 1; --overlay-transition: 0.3s; --e-con-grid-template-columns: repeat(3,1fr); --e-con-grid-template-rows: repeat(2,1fr); position: relative; width: 100%; min-width: 0px; min-height: 0px; height: auto; border-radius: 20px; z-index: auto; overflow: visible; transition: background 0.3s, border 0.3s, box-shadow 0.3s, transform 0.4s; --flex-wrap-mobile: wrap; margin-block: 25px 15px; margin-inline: 0px; padding-inline: 15px; --margin-block-start: 25px; --margin-block-end: 15px; --margin-inline-start: 0px; --margin-inline-end: 0px; --padding-inline-start: 15px; --padding-inline-end: 15px; --padding-block-start: 15px; --padding-block-end: 15px; --border-block-start-width: 0px; --border-block-end-width: 0px; --border-inline-start-width: 0px; --border-inline-end-width: 0px; padding-block: 15px; display: flex; --swiper-theme-color: #000; --swiper-navigation-size: 44px; --swiper-pagination-bullet-size: 6px; --swiper-pagination-bullet-horizontal-gap: 6px; --container-max-width: 1200px; --container-default-padding-top: 0px; --container-default-padding-right: 0px; --container-default-padding-bottom: 0px; --container-default-padding-left: 0px; --widgets-spacing: 20px 20px; --widgets-spacing-row: 20px; --widgets-spacing-column: 20px; max-width: 100%; --display: flex; --background-transition: 0.3s; box-shadow: rgba(63, 63, 75, 0.22) 0.01px 0.01px 35px -3px; --border-transition: 0.3s; background-color: rgb(10, 24, 69);\"><div class=\"elementor-element elementor-element-38f2150 e-con-full e-flex e-con e-child\" data-id=\"38f2150\" data-element_type=\"container\" style=\"--flex-direction: column; --flex-wrap: initial; --justify-content: flex-start; --align-items: initial; --align-content: initial; --gap: 4px 4px; --flex-basis: auto; --flex-grow: 0; --flex-shrink: 1; --order: initial; --align-self: initial; flex: 0 1 auto; order: 0; align-self: auto; flex-flow: column; place-content: normal flex-start; align-items: normal; gap: 4px; --border-radius: 0; --border-top-width: 0px; --border-right-width: 0px; --border-bottom-width: 0px; --border-left-width: 0px; --border-style: initial; --border-color: initial; --container-widget-width: 100%; --container-widget-height: initial; --container-widget-flex-grow: 0; --container-widget-align-self: initial; --content-width: min(100%,1200px); --width: 70%; --min-height: initial; --height: auto; --text-align: initial; --margin-top: 0px; --margin-right: 0px; --margin-bottom: 0px; --margin-left: 0px; --padding-top: 10px; --padding-right: 10px; --padding-bottom: 10px; --padding-left: 10px; --position: relative; --z-index: revert; --overflow: visible; --overlay-mix-blend-mode: initial; --overlay-opacity: 1; --overlay-transition: 0.3s; --e-con-grid-template-columns: repeat(3,1fr); --e-con-grid-template-rows: repeat(2,1fr); position: relative; width: 70%; min-width: 0px; min-height: auto; height: auto; border-radius: 0px; z-index: auto; overflow: visible; transition: background 0.3s, border 0.3s, box-shadow 0.3s, transform 0.4s; --flex-wrap-mobile: wrap; margin-block: 0px; margin-inline: 0px; padding-inline: 10px; --margin-block-start: 0px; --margin-block-end: 0px; --margin-inline-start: 0px; --margin-inline-end: 0px; --padding-inline-start: 10px; --padding-inline-end: 10px; --padding-block-start: 10px; --padding-block-end: 10px; --border-block-start-width: 0px; --border-block-end-width: 0px; --border-inline-start-width: 0px; --border-inline-end-width: 0px; padding-block: 10px; display: flex; --swiper-theme-color: #000; --swiper-navigation-size: 44px; --swiper-pagination-bullet-size: 6px; --swiper-pagination-bullet-horizontal-gap: 6px; --container-max-width: 1200px; --container-default-padding-top: 0px; --container-default-padding-right: 0px; --container-default-padding-bottom: 0px; --container-default-padding-left: 0px; --widgets-spacing: 20px 20px; --widgets-spacing-row: 20px; --widgets-spacing-column: 20px; --display: flex; --background-transition: 0.3s;\"><div class=\"elementor-element elementor-element-470d4c4 elementor-widget elementor-widget-heading\" data-id=\"470d4c4\" data-element_type=\"widget\" data-widget_type=\"heading.default\" style=\"--flex-direction: initial; --flex-wrap: initial; --justify-content: initial; --align-items: initial; --align-content: initial; --gap: initial; --flex-basis: initial; --flex-grow: initial; --flex-shrink: initial; --order: initial; --align-self: center; flex: 0 1 auto; order: 0; align-self: center; flex-flow: row; place-content: normal; align-items: normal; gap: normal; position: relative; --swiper-theme-color: #000; --swiper-navigation-size: 44px; --swiper-pagination-bullet-size: 6px; --swiper-pagination-bullet-horizontal-gap: 6px; --widgets-spacing: 20px 20px; --widgets-spacing-row: 20px; --widgets-spacing-column: 20px; margin-bottom: 20px; min-width: 0px; margin-block-end: 0px; max-width: 100%;\"><div class=\"elementor-widget-container\" style=\"transition: background 0.3s, border 0.3s, border-radius 0.3s, box-shadow 0.3s, transform 0.4s; height: 32px;\"><div class=\"elementor-heading-title elementor-size-default\" style=\"padding: 0px; margin: 0px; line-height: 1; color: rgb(255, 255, 255); font-family: Karla, sans-serif; font-weight: 600;\"><span style=\"font-size: 2rem;\">Save on your Foundayo order</span></div></div></div><div class=\"elementor-element elementor-element-3944e14 elementor-widget elementor-widget-heading\" data-id=\"3944e14\" data-element_type=\"widget\" data-widget_type=\"heading.default\" style=\"--flex-direction: initial; --flex-wrap: initial; --justify-content: initial; --align-items: initial; --align-content: initial; --gap: initial; --flex-basis: initial; --flex-grow: 1; --flex-shrink: 1; --order: initial; --align-self: center; flex: 1 1 auto; order: 0; align-self: center; flex-flow: row; place-content: normal; align-items: normal; gap: normal; position: relative; --swiper-theme-color: #000; --swiper-navigation-size: 44px; --swiper-pagination-bullet-size: 6px; --swiper-pagination-bullet-horizontal-gap: 6px; --widgets-spacing: 20px 20px; --widgets-spacing-row: 20px; --widgets-spacing-column: 20px; min-width: 0px; margin-block-end: 0px; max-width: 100%;\"><div class=\"elementor-widget-container\" style=\"transition: background 0.3s, border 0.3s, border-radius 0.3s, box-shadow 0.3s, transform 0.4s; height: 16px;\"><div class=\"elementor-heading-title elementor-size-default\" style=\"padding: 0px; margin: 0px; line-height: 1; color: rgb(255, 255, 255); font-family: Karla, sans-serif; font-size: 1px;\"><div><span style=\"font-size: 1rem;\">Starting from<span style=\"font-weight: bolder;\"> £59</span> when you<span style=\"font-weight: bolder;\"> Subscribe &amp; Save</span></span></div></div></div></div></div><a class=\"elementor-element elementor-element-7adebae e-con-full e-flex e-con e-child\" data-id=\"7adebae\" data-element_type=\"container\" data-settings=\"{&quot;background_background&quot;:&quot;classic&quot;,&quot;background_motion_fx_motion_fx_mouse&quot;:&quot;yes&quot;}\" href=\"https://www.simpleonlinepharmacy.co.uk/online-doctor/weight-loss-pills/foundayo/\" style=\"background-color: rgb(255, 204, 23); color: rgb(29, 92, 255); text-decoration: none; --flex-direction: row; --flex-wrap: initial; --justify-content: center; --align-items: center; --align-content: initial; --gap: 10px 10px; --flex-basis: auto; --flex-grow: 0; --flex-shrink: 1; --order: initial; --align-self: initial; flex: 0 1 auto; order: 0; align-self: auto; flex-flow: row; place-content: normal center; align-items: center; gap: 10px; --border-radius: 90px 90px 90px 90px; --border-top-width: 0px; --border-right-width: 0px; --border-bottom-width: 0px; --border-left-width: 0px; --border-style: none; --border-color: initial;