INSERT INTO `products` (`id`, `category_id`, `title`, `price`, `keyphrase`, `slug`, `image`, `overview`, `content`, `p_user_fk`, `drug_type`, `created_at`, `updated_at`) VALUES
(3, 1, 'Tadalafil', 23.00, 'Tadalafil', 'tadalafil', 'public/assets/uploads/b42d30612287c2e33e2b359edb8b6e26.webp', 'Tadalafil is a medication used to treat erectile dysfunction (ED) in men, helping to achieve and maintain an erection. It works by increasing blood flow to the penis, and its effects can last up to 36 hours.', '<h2 id=\"buy-online\" class=\"collapsible-header\" style=\"margin: 0px 0px 8px; color: rgb(0, 68, 204); font-family: Karla, sans-serif; font-weight: bold; line-height: normal; font-size: 18px; cursor: pointer; border: 1px solid rgb(153, 204, 255); background-color: rgb(248, 252, 255); padding: 12px; border-radius: 8px; text-align: center;\">Buy Tadalafil Tablets Online in the UK</h2><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">You can buy Tadalafil tablets for erectile dysfunction online from our UK-registered doctor and pharmacy service. This clinically proven treatment provides effective, long-lasting results, helping you take control of your health with ease.</p><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">Simply complete a quick online assessment, and our UK-registered doctors will review your suitability for treatment. If approved, your prescription is sent to our pharmacy team, who will dispense and securely deliver your medication to your chosen address-discreetly and hassle-free.</p><h2 id=\"tadalafil-summary\" class=\"collapsible-header\" style=\"margin: 0px 0px 8px; color: rgb(0, 68, 204); font-family: Karla, sans-serif; font-weight: bold; line-height: normal; font-size: 18px; cursor: pointer; border: 1px solid rgb(153, 204, 255); background-color: rgb(248, 252, 255); padding: 12px; border-radius: 8px; text-align: center;\">Summary</h2><table class=\"\" style=\"width: 683.667px; border-spacing: 0px; margin: 8px 0px; border: 1px solid rgb(153, 204, 255); table-layout: fixed; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif; background-color: rgb(248, 252, 255);\"><tbody><tr style=\"border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: none !important;\"><td class=\"xl68\" style=\"padding: 10px; line-height: 27px; font-size: 18px; opacity: 0.8; width: 136.729px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\"><span style=\"font-weight: bolder;\">What is it?</span></td><td class=\"xl69\" style=\"padding: 10px; line-height: 27px; font-size: 18px; opacity: 0.8; width: 546.938px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\"><p class=\"align--left\" style=\"margin: 0px 0px 10px; line-height: 27px;\">Effective treatment for Erectile Dysfunction</p></td></tr><tr style=\"background: rgb(246, 246, 246); border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: none !important;\"><td class=\"xl68\" style=\"padding: 10px; line-height: 27px; font-size: 18px; opacity: 0.8; width: 136.729px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\"><span style=\"font-weight: bolder;\">How does it work?</span></td><td class=\"xl69\" style=\"padding: 10px; line-height: 27px; font-size: 18px; opacity: 0.8; width: 546.938px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\"><p class=\"align--left\" style=\"margin: 0px 0px 10px; line-height: 27px;\">Tadalafil is part of the group of pde5 inhibitors, which work by improving and increasing the flow of blood into your penis. This results in a firmer and longer-lasting erection.</p></td></tr><tr style=\"border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: none !important;\"><td class=\"xl68\" style=\"padding: 10px; line-height: 27px; font-size: 18px; opacity: 0.8; width: 136.729px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\"><span style=\"font-weight: bolder;\">How effective is it?</span></td><td class=\"xl69\" style=\"padding: 10px; line-height: 27px; font-size: 18px; opacity: 0.8; width: 546.938px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\"><p style=\"margin: 0px 0px 10px; line-height: 27px;\">Over 80% of men will notice a firmer and longer-lasting erection.</p><p style=\"margin: 0px 0px 10px; line-height: 27px;\">If Tadalafil doesn’t work for you the first time around, it could nevertheless be more effective next time. Doctors often advise trying all erectile dysfunction medicines eight times before giving up.</p></td></tr><tr style=\"background: rgb(246, 246, 246); border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: none !important;\"><td class=\"xl68\" style=\"padding: 10px; line-height: 27px; font-size: 18px; opacity: 0.8; width: 136.729px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\"><span style=\"font-weight: bolder;\">What\'s the dose?</span></td><td class=\"xl69\" style=\"padding: 10px; line-height: 27px; font-size: 18px; opacity: 0.8; width: 546.938px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\"><p style=\"margin: 0px 0px 10px; line-height: 27px;\">10mg / 20mg: Take ONE tablet 30 minutes before sex.</p><p style=\"margin: 0px 0px 10px; line-height: 27px;\">Never take more than ONE tablet within 36 hours</p><p style=\"margin: 0px 0px 10px; line-height: 27px;\">2.5mg / 5mg: You should take ONE tablet DAILY</p><p style=\"margin: 0px 0px 10px; line-height: 27px;\">Although Tadalafil can be taken with food, this may slow down the time it takes for the drug to work.</p></td></tr><tr style=\"border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: none !important;\"><td class=\"xl68\" style=\"padding: 10px; line-height: 27px; font-size: 18px; opacity: 0.8; width: 136.729px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\"><span style=\"font-weight: bolder;\">Side effects</span></td><td class=\"xl69\" style=\"padding: 10px; line-height: 27px; font-size: 18px; opacity: 0.8; width: 546.938px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\"><p class=\"align--left\" style=\"margin: 0px 0px 10px; line-height: 27px;\">Can include nausea, vomiting, and diarrhoea. Tadalafil can also cause nasal congestion, headaches, facial flushing, slight vertigo, a pounding heartbeat, and blurred vision.</p></td></tr></tbody></table><h2 id=\"what-is-tadalafil\" class=\"collapsible-header\" style=\"margin: 0px 0px 8px; color: rgb(0, 68, 204); font-family: Karla, sans-serif; font-weight: bold; line-height: normal; font-size: 18px; cursor: pointer; border: 1px solid rgb(153, 204, 255); background-color: rgb(248, 252, 255); padding: 12px; border-radius: 8px; text-align: center;\">What Is It?</h2><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">Tadalafil is a drug used to treat erectile dysfunction in men. It does this by improving blood flow to the penis when sexually stimulated. This allows men who suffer from ED to achieve firmer and longer-lasting erections.</p><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">It is available in 4 strengths, ranging from 2.5mg to 20mg. Tadalafil 20mg is the most commonly used dosage, and is also the strongest. It is taken as required (when needed for sex). The lower doses are taken daily to maintain levels of Tadalafil in your system, so you can be ready for sex at anytime.</p><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">Tadalafil is the active ingredient in the well known erectile dysfunction drug Cialis. As of 2017, Cialis no longer has an exclusive patent on this drug, and this means that other companies are able to manufacture Tadalafil.</p><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">While medically the same, the competition means prices for generic medicines are cheaper than the original versions.</p><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">Tadalafil generic is also the version prescribed by the NHS for eligible patients.</p><h2 id=\"how-tadalafil-works\" class=\"collapsible-header\" style=\"margin: 0px 0px 8px; color: rgb(0, 68, 204); font-family: Karla, sans-serif; font-weight: bold; line-height: normal; font-size: 18px; cursor: pointer; border: 1px solid rgb(153, 204, 255); background-color: rgb(248, 252, 255); padding: 12px; border-radius: 8px; text-align: center;\">How It Works</h2><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">Tadalafil, like other ED treatments such as sildenafil (Viagra), vardenafil (Levitra), and avanafil (Spedra), works by increasing the blood flow into your penis by relaxing the blood vessels which flow into them.</p><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">It achieves this effect by blocking an enzyme called PDE5. As a group, these drugs are called \'PDE5 inhibitors\'. Because they have very little effect on other parts of the body, there are generally well tolerated and safe medications. As a result, some forms of these drugs have been made available over the counter in the UK, such as <a title=\"viagra connect\" href=\"https://www.simpleonlinepharmacy.co.uk/online-doctor/erectile-dysfunction/viagra-connect/\" style=\"text-decoration: none; outline: 0px; opacity: 0.8; color: rgb(0, 35, 126) !important;\">Viagra Connect</a>.</p><h2 id=\"why-tadalafil\" class=\"collapsible-header\" style=\"margin: 0px 0px 8px; color: rgb(0, 68, 204); font-family: Karla, sans-serif; font-weight: bold; line-height: normal; font-size: 18px; cursor: pointer; border: 1px solid rgb(153, 204, 255); background-color: rgb(248, 252, 255); padding: 12px; border-radius: 8px; text-align: center;\">Why Tadalafil?</h2><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">With a number of ED drugs available, many men are unsure which medication is right for them. The main advantage of Tadalafil over Sildenafil, Viagra, Levitra, and Spedra, is the length of action.</p><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">What does this mean? Basically, the effects of Tadalafil can last for up to 72 hours after taking a dose. It should be noted, this does not mean that your erection will last this long! In fact, any erection which is painful or lasts more than 4 hours should be brought to the attention of your doctor immediately. The 72-hour effect simply means that you should be able to achieve an erection when sexually stimulated, in the 3 days after taking the pill.</p><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">You can find out more about experiences with this medication, from our UK <a title=\"tadalafil reviews\" href=\"https://www.simpleonlinepharmacy.co.uk/health-advice/erectile-dysfunction/tadalafil/tadalafil-reviews/\" style=\"text-decoration: none; outline: 0px; opacity: 0.8; color: rgb(0, 35, 126) !important;\">patient Tadalafil reviews</a>.</p><h2 id=\"tadalafil-dosage\" class=\"collapsible-header\" style=\"margin: 0px 0px 8px; color: rgb(0, 68, 204); font-family: Karla, sans-serif; font-weight: bold; line-height: normal; font-size: 18px; cursor: pointer; border: 1px solid rgb(153, 204, 255); background-color: rgb(248, 252, 255); padding: 12px; border-radius: 8px; text-align: center;\">Tadalafil Dosage</h2><h3 class=\"\" style=\"margin: 0px 0px 8px; color: rgb(0, 68, 204); font-family: Karla, sans-serif; font-weight: bold; line-height: 36px; font-size: 18px; border: 1px solid rgb(153, 204, 255); background-color: rgb(241, 243, 244); padding: 12px; border-radius: 8px; text-align: center;\">Tadalafil 20mg</h3><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">Both Tadalafil 20mg and 10mg are \'when required\' doses, so should be taken around 30 minutes before sexual activity. 20mg is the maximum allowable dose. If you have found that this dose is not effective for you, it may be that this medicine is not for you. Speak to your GP for further options. If you have liver problems, speak to your GP before taking this because the dose may need to be reduced.</p><h3 class=\"\" style=\"margin: 0px 0px 8px; color: rgb(0, 68, 204); font-family: Karla, sans-serif; font-weight: bold; line-height: 36px; font-size: 18px; border: 1px solid rgb(153, 204, 255); background-color: rgb(241, 243, 244); padding: 12px; border-radius: 8px; text-align: center;\">Tadalafil 5mg</h3><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">Tadalafil 2.5mg and 5mg are known as Tadalafil Daily dose tablets. These are designed as daily dosages. You should take one tablet daily to help maintain the levels of Tadalafil in the bloodstream.</p><h3 class=\"\" style=\"margin: 0px 0px 8px; color: rgb(0, 68, 204); font-family: Karla, sans-serif; font-weight: bold; line-height: 36px; font-size: 18px; border: 1px solid rgb(153, 204, 255); background-color: rgb(241, 243, 244); padding: 12px; border-radius: 8px; text-align: center;\">Adjustments</h3><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">If you notice your erections are lasting too long, or you are not achieving an erection for long enough, you can adjust your dosage as appropriate. Remember; if taking Tadalafil daily, the maximum dosage is 5mg. If taking Tadalafil when required, the maximum dosage in a 72 hour period is 20mg as a single dose. You may find that to solve your ED issues you only need to take a 5mg tablet every 2-3 days.</p><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">Every patient is different, so you should adjust your dose according to the results. It is better to take as little medicine as possible, as this reduces the chances of potential side effects. If you are able to configure your dosage effectively, this will also save you money!</p><table class=\"\" style=\"width: 683.667px; border-spacing: 0px; margin: 8px 0px; border: 1px solid rgb(153, 204, 255); table-layout: fixed; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif; background-color: rgb(248, 252, 255);\"><tbody><tr style=\"height: 199.375px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: none !important;\"><td style=\"padding: 10px; text-align: center; line-height: 27px; font-size: 18px; opacity: 0.8; height: 199.375px; width: 205.094px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\"><img src=\"https://www.albynpharmacy.com/wp-content/uploads/2021/03/Tadalafil-2.5mg.jpg\" alt=\"Tadalafil 2.5mg\" style=\"width: auto;\"></td><td style=\"padding: 10px; text-align: center; line-height: 27px; font-size: 18px; opacity: 0.8; height: 199.375px; width: 478.573px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\"><p style=\"margin: 0px 0px 10px; line-height: 27px;\">Cialis 2.5mg</p><p style=\"margin: 0px 0px 10px; line-height: 27px;\">The daily dosage used when 5mg is too strong</p></td></tr><tr style=\"background: rgb(246, 246, 246); height: 11px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: none !important;\"><td style=\"padding: 10px; line-height: 27px; font-size: 18px; opacity: 0.8; height: 11px; width: 193.406px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\"><p style=\"margin: 0px 0px 10px; line-height: 27px; text-align: center;\"><img src=\"https://www.albynpharmacy.com/wp-content/uploads/2021/03/Tadalafil-5mg.jpg\" alt=\"Tadalafil Daily\" style=\"width: auto;\"></p></td><td style=\"padding: 10px; line-height: 27px; font-size: 18px; opacity: 0.8; height: 11px; width: 332.594px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\"><p style=\"margin: 0px 0px 10px; line-height: 27px; text-align: center;\">Cialis 5mg</p><p style=\"margin: 0px 0px 10px; line-height: 27px; text-align: center;\">Tablet preferred if Tadalafil is established to be effective and the patient prefers daily rather than when required dosing</p></td></tr><tr style=\"height: 11px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: none !important;\"><td style=\"padding: 10px; line-height: 27px; font-size: 18px; opacity: 0.8; height: 11px; width: 193.406px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\"><p style=\"margin: 0px 0px 10px; line-height: 27px; text-align: center;\">&nbsp;</p><p style=\"margin: 0px 0px 10px; line-height: 27px;\"><img src=\"https://www.albynpharmacy.com/wp-content/uploads/2021/03/Tadalafil-10mg.jpg\" alt=\"Tadalafil 10mg\" style=\"width: auto;\"></p></td><td style=\"padding: 10px; text-align: center; line-height: 27px; font-size: 18px; opacity: 0.8; height: 11px; width: 332.594px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\"><p style=\"margin: 0px 0px 10px; line-height: 27px;\">Cialis 10mg</p><p style=\"margin: 0px 0px 10px; line-height: 27px;\">Common starting dose. Used only just prior to sexual activity.</p></td></tr><tr style=\"background: rgb(246, 246, 246); height: 11px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: none !important;\"><td style=\"padding: 10px; line-height: 27px; font-size: 18px; opacity: 0.8; height: 11px; width: 193.406px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\"><img src=\"https://www.albynpharmacy.com/wp-content/uploads/2021/03/Tadalafil-20mg.jpg\" alt=\"Tadalafil 20mg\" style=\"width: auto;\"></td><td style=\"padding: 10px; text-align: center; line-height: 27px; font-size: 18px; opacity: 0.8; height: 11px; width: 332.594px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\"><p style=\"margin: 0px 0px 10px; line-height: 27px;\">Cialis 20mg</p><p style=\"margin: 0px 0px 10px; line-height: 27px;\">Also used just prior to sexual activity. Usually used when 10mg is ineffective.</p></td></tr></tbody></table><h3 id=\"dosageinformation\" class=\"\" style=\"margin: 0px 0px 8px; color: rgb(0, 68, 204); font-family: Karla, sans-serif; font-weight: bold; line-height: 36px; font-size: 18px; border: 1px solid rgb(153, 204, 255); background-color: rgb(241, 243, 244); padding: 12px; border-radius: 8px; text-align: center;\">Daily Dosing</h3><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">If a 10mg or 20mg dosage is successful in treating your ED, you may wish to consider using the 2.5mg or 5mg daily dose. The reason men may use this daily dose is that it maintains levels of Tadalafil in the blood all the time. This means you do not need to remember to take it each time you wish to have sex. Simply take the daily tablet each day, and this should mean you can achieve an erection, whenever you come to engage in sexual activity.</p><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">The convenience of not needing to take your medication with you everywhere, and simply taking it with your breakfast each morning, is a change in how traditional ED medications have worked.</p><h2 id=\"tadalafil-side-effects\" class=\"collapsible-header\" style=\"margin: 0px 0px 8px; color: rgb(0, 68, 204); font-family: Karla, sans-serif; font-weight: bold; line-height: normal; font-size: 18px; cursor: pointer; border: 1px solid rgb(153, 204, 255); background-color: rgb(248, 252, 255); padding: 12px; border-radius: 8px; text-align: center;\">Side Effects of Tadalafil</h2><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">The most commons side effects of Tadalafil are</p><ul class=\"\" style=\"margin: 0px 0px 30px; padding: 0px 0px 0px 20px; max-width: 992px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\"><li style=\"list-style-type: disc; max-width: 100%; float: left; width: 663.667px;\">Headaches</li><li style=\"list-style-type: disc; max-width: 100%; border-left: 1px solid rgb(255, 255, 255); float: left; width: 663.667px;\">Flushing</li><li style=\"list-style-type: disc; max-width: 100%; border-left: 1px solid rgb(255, 255, 255); float: left; width: 663.667px;\">Runny/stuffy nose</li><li style=\"list-style-type: disc; max-width: 100%; border-left: 1px solid rgb(255, 255, 255); float: left; width: 663.667px;\">Upset stomach</li><li style=\"list-style-type: disc; max-width: 100%; border-left: 1px solid rgb(255, 255, 255); float: left; width: 663.667px;\">Nausea</li><li style=\"list-style-type: disc; max-width: 100%; border-left: 1px solid rgb(255, 255, 255); float: left; width: 663.667px;\">Red and/or warm skin</li><li style=\"list-style-type: disc; max-width: 100%; border-left: 1px solid rgb(255, 255, 255); float: left; width: 663.667px;\">Dizziness</li></ul><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">Those listed below are more serious, and you should stop taking Tadalafil, and report these to your doctor immediately.</p><ul class=\"\" style=\"margin: 0px 0px 30px; padding: 0px 0px 0px 20px; max-width: 992px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\"><li style=\"list-style-type: disc; max-width: 100%; float: left; width: 663.667px;\">An erection that will not go away (priapism). If you have an erection that lasts more than 4 hours, seek medical help immediately. Priapism can permanently damage your penis.</li><li style=\"list-style-type: disc; max-width: 100%; border-left: 1px solid rgb(255, 255, 255); float: left; width: 663.667px;\">Sudden vision loss in one or both eyes. Sudden vision loss in one or both eyes can be a sign of a serious eye problem called non-arteritic anterior ischemic optic neuropathy (NAION).</li><li style=\"list-style-type: disc; max-width: 100%; border-left: 1px solid rgb(255, 255, 255); float: left; width: 663.667px;\">Sudden hearing decrease or hearing loss. Some people may also have ringing in their ears (tinnitus) or dizziness.</li></ul><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">For a full list of side effects, please read the <a href=\"https://www.medicines.org.uk/emc/product/15292/pil\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"text-decoration: none; outline: 0px; opacity: 0.8; color: rgb(0, 35, 126) !important;\">patient information leaflet</a>.</p><h2 id=\"tadalafil-alternatives\" class=\"collapsible-header\" style=\"margin: 0px 0px 8px; color: rgb(0, 68, 204); font-family: Karla, sans-serif; font-weight: bold; line-height: normal; font-size: 18px; cursor: pointer; border: 1px solid rgb(153, 204, 255); background-color: rgb(248, 252, 255); padding: 12px; border-radius: 8px; text-align: center;\">Alternatives</h2><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">Tadalafil is not the only treatment option for sufferers of erectile dysfunction. You may wish to choose other drugs to treat your ED, or even try a drug-free approach.</p><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">Depending on the cause of your erectile dysfunction, it is<a href=\"https://www.health.harvard.edu/mens-health/5-natural-ways-to-overcome-erectile-dysfunction\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"text-decoration: none; outline: 0px; opacity: 0.8; color: rgb(0, 35, 126) !important;\"> possible that you could resolve your symptoms without taking any medication</a>. For example, alcohol can be a cause of ED, and if your intake is high, you can try reducing your weekly intake to see if this helps. If you are overweight, you may also find trouble getting and maintaining an erection. Losing weight can improve erectile dysfunction.</p><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">Counselling can also be helpful if anxiety and stress play a role in your symptoms.</p><p class=\"\" style=\"margin: 0px 0px 10px; line-height: 27px; font-size: 18px; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif;\">In terms of other ED medicines available, the branded version of Tadalafil,<a href=\"https://www.simpleonlinepharmacy.co.uk/online-doctor/erectile-dysfunction/cialis/\" style=\"text-decoration: none; outline: 0px; opacity: 0.8; color: rgb(0, 35, 126) !important;\"> Cialis</a> is an option. <a href=\"https://www.simpleonlinepharmacy.co.uk/online-doctor/erectile-dysfunction/viagra/\" style=\"text-decoration: none; outline: 0px; opacity: 0.8; color: rgb(0, 35, 126) !important;\">Viagra</a> and<a href=\"https://www.simpleonlinepharmacy.co.uk/online-doctor/erectile-dysfunction/sildenafil/\" style=\"text-decoration: none; outline: 0px; opacity: 0.8; color: rgb(0, 35, 126) !important;\"> Sildenafil</a> are also alternatives, and while they do not provide as long lasting an effect, they are very effective ED treatments.<a href=\"https://www.simpleonlinepharmacy.co.uk/online-doctor/erectile-dysfunction/levitra/\" style=\"text-decoration: none; outline: 0px; opacity: 0.8; color: rgb(0, 35, 126) !important;\"> Levitra</a> and<a href=\"https://www.simpleonlinepharmacy.co.uk/online-doctor/erectile-dysfunction/spedra/\" style=\"text-decoration: none; outline: 0px; opacity: 0.8; color: rgb(0, 35, 126) !important;\"> Spedra</a> are the other ED treatments available in the UK, which also have some advantages depending on the patient. Whether you choose a branded drug or one of the generic medicines, check you are ordering from a trusted source.</p><h2 id=\"tadalafil-prices\" class=\"collapsible-header\" style=\"margin: 0px 0px 8px; color: rgb(0, 68, 204); font-family: Karla, sans-serif; font-weight: bold; line-height: normal; font-size: 18px; cursor: pointer; border: 1px solid rgb(153, 204, 255); background-color: rgb(248, 252, 255); padding: 12px; border-radius: 8px; text-align: center;\">Prices</h2><table border=\"1\" width=\"100%\" class=\"\" style=\"width: 683.667px; border-spacing: 0px; margin: 8px 0px; border: 1px solid rgb(153, 204, 255); table-layout: fixed; color: rgb(29, 33, 36); font-family: &quot;Oakes Grotesk&quot;, sans-serif; background-color: rgb(248, 252, 255);\"><tbody><tr style=\"height: 13px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: none !important;\"><td width=\"35%\" style=\"padding: 10px; line-height: 27px; font-size: 18px; opacity: 0.8; height: 13px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\">Tadalafil - 4 tablets</td><td width=\"65%\" style=\"padding: 10px; line-height: 27px; font-size: 18px; opacity: 0.8; height: 13px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\">from £8.95</td></tr><tr style=\"background: rgb(246, 246, 246); height: 13px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: none !important;\"><td style=\"padding: 10px; line-height: 27px; font-size: 18px; opacity: 0.8; height: 13px; border-width: medium !important; border-style: none !important; border-color: currentcolor !important;\">Tadalafil - 8 tablets</td><td style=\"padding: